    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
}

.settings-sidebar ul {
    list-style: none;
    margin: 0;
    padding: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    font-weight: 500;
    transition: background 0.15s, border-left 0.15s;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
}

.settings-sidebar li.active {
    background: #e3f2fd;
    border-left-color: #1976d2;
    color: #1976d2;
}

/* Content Area */
.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.95rem;
}

.form-group textarea {
    resize: vertical;
}

.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn-primary {
    background: #1976d2;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover {
    background: #1565c0;
}

.btn-secondary {
    background: #6c757d;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-secondary:hover {
    background: #5a6268;
}

.btn-danger {
    background: #d32f2f;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-danger:hover {
    background: #c62828;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle Rows */
.toggle-group {
    margin-bottom: 1.5rem;
}

.toggle-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    cursor: pointer;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.avatar-preview img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    background: #e0e0e0;
}

.avatar-url {
    font-size: 0.85rem;
    color: #666;
    word-break: break-all;
}

