    border: 1px solid #ddd;
    border-radius: 4px;
}

.preview-card .preview-title {
    display: block;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.preview-card .preview-text {
    font-size: 0.9rem;
    color: #555;
}

/* Preview Theme Variants */
.preview-area.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-dark .preview-card {
    border-color: #555;
    background: #2d2d2d;
}

.preview-area.theme-dark .preview-text {
    color: #bbb;
}

.preview-area.theme-light {
    background: #ffffff;
    color: #212121;
}

.preview-area.theme-system {
    background: #fafafa;
    color: #333;
}

/* Preview Font Sizes */
.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.2rem;
}

/* Preview Compact Mode */
.preview-area.compact {
    padding: 0.5rem;
    line-height: 1.2;
}

.preview-area.compact .preview-card {
    padding: 0.4rem;
    margin-top: 0.4rem;
}

