+    color: #c62828;
+    border: 1px solid #ef9a9a;
+}
+
+/* Expandable Panel */
+.expandable-panel {
+    border: 1px solid #e0e0e0;
+    border-radius: 4px;
+    margin-bottom: 1.5rem;
+}
+
+.panel-header {
+    width: 100%;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.75rem 1rem;
+    background: #f8f9fa;
+    border: none;
+    cursor: pointer;
+    font-size: 1rem;
+    font-weight: 500;
+}
+
+.panel-header:hover {
+    background: #e9ecef;
+}
+
+.panel-content {
+    padding: 1rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+/* Two-Factor Section */
+.two-factor-section {
+    margin-bottom: 1.5rem;
+}
+
+.status-row {
+    display: flex;
+    align-items: center;
+    gap: 1.5rem;
+}
+
+.status-indicator.enabled {
+    color: #2e7d32;
+    font-weight: 500;
+}
+
+.status-indicator.disabled {
+    color: #9e9e9e;
+}
+
+.info-text {
+    font-size: 0.85rem;
+    color: #666;
+    margin-top: 0.5rem;
+}
+
+/* Sessions Table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-top: 0.75rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    text-align: left;
+    padding: 0.6rem 0.75rem;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    font-size: 0.85rem;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    color: #1976d2;
+    font-weight: 500;
+}
+
+/* Dialog Overlay */
+.dialog-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.dialog {
+    background: white;
+    border-radius: 8px;
+    padding: 1.5rem;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
+}
+
+.dialog h4 {
+    margin-top: 0;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.25rem;
+    justify-content: flex-end;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+}
+
+.radio-option {
+    display: flex;
+    align-items: center;
+    gap: 0.35rem;
+    cursor: pointer;
+}
+
+/* Channel List */
+.channel-list {
+    margin-bottom: 1rem;
+    padding-left: 0.25rem;
+}
+
+/* Appearance Preview */
+.preview-area {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-top: 1.5rem;
+    transition: all 0.2s;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+    margin-bottom: 0.5rem;
+}
+
+.preview-card {
+    margin-top: 0.75rem;
+    padding: 0.75rem;
+    border: 1px solid #ddd;
+    border-radius: 4px;
+}
+
+.preview-card .preview-title {
+    display: block;
+    font-weight: 600;
+    margin-bottom: 0.25rem;
+}
+
+.preview-card .preview-text {
+    font-size: 0.9rem;
+    color: #555;
+}
+
+/* Preview Theme Variants */
+.preview-area.theme-dark {
+    background: #1e1e1e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-area.theme-dark .preview-card {
+    border-color: #555;
+    background: #2d2d2d;
+}
+
+.preview-area.theme-dark .preview-text {
+    color: #bbb;
+}
+
+.preview-area.theme-light {
+    background: #ffffff;
+    color: #212121;
+}
+
+.preview-area.theme-system {
+    background: #fafafa;
+    color: #333;
+}
+
+/* Preview Font Sizes */
+.preview-area.font-small {
+    font-size: 0.8rem;
+}
+
+.preview-area.font-medium {
+    font-size: 1rem;
+}
+
+.preview-area.font-large {
+    font-size: 1.2rem;
+}
+
+/* Preview Compact Mode */
+.preview-area.compact {
+    padding: 0.5rem;
+    line-height: 1.2;
+}
+
+.preview-area.compact .preview-card {
+    padding: 0.4rem;
+    margin-top: 0.4rem;
+}
+

